#include <metal_stdlib>
using namespace metal;
#pragma clang fp contract(off)
inline long b2_timestep(float value, float dt, thread bool *fault) {
    float steps = (value + 1e-3f*dt)/dt;
    if (!(value >= 0.0f && isfinite(dt) && dt > 0.0f && isfinite(steps) && steps <= 0x1p53f)) {
        *fault = true;
        return 0;
    }
    return long(steps);
}
inline long b2_tick_offset(long tick, long offset, thread bool *fault) {
    // Frozen B2IR evaluates logical ticks as f64. The boundary ties
    // +(2^53+1) and -(2^53+1) round to +/-2^53 and are accepted there.
    // Check before addition so even invalid inputs cannot overflow int64.
    const long limit = 9007199254740992l;
    const long allowed = limit + 1l;
    if (tick > allowed-offset || tick < -allowed-offset) {
        *fault = true;
        return 0;
    }
    long result = tick + offset;
    return result > limit ? limit : (result < -limit ? -limit : result);
}
inline float b2_finite(float value, thread bool *error) {
    if (!isfinite(value)) { *error = true; return 0.0f; }
    return value;
}
inline float b2_clip(float value, float lo, float hi) {
    // B2IR defines ordered max/min even when bounds are reversed. std::clamp
    // has a precondition lo <= hi and is not this operation.
    return fmin(fmax(value,lo),hi);
}
inline float b2_powi(float x, int power) {
    uint n = uint(power < 0 ? -power : power);
    float result = 1.0f;
    while (n) { if (n & 1u) result *= x; x *= x; n >>= 1; }
    return power < 0 ? 1.0f/result : result;
}
inline float b2_exp(float x) {
    if (x > 88.722839f) return INFINITY;
    if (x < -103.97208f) return 0.0f;
    float nf = floor(x*1.4426950408889634f + 0.5f);
    int n = int(nf);
    float r = (x - nf*0.693359375f) - nf*(-0.00021219444005469058f);
    float p = 1.0f/5040.0f;
    p = 1.0f/720.0f + r*p;
    p = 1.0f/120.0f + r*p;
    p = 1.0f/24.0f + r*p;
    p = 1.0f/6.0f + r*p;
    p = 0.5f + r*p;
    float value = 1.0f + (r + r*r*p);
    float result = ldexp(value, n);
    // Metal arithmetic flushes subnormals; make the shared exp contract explicit.
    return fabs(result) < 0x1p-126f ? 0.0f : result;
}
inline float b2_expm1(float x) {
    if (abs(x) < 0.001f) return x * (1.0f + x * (0.5f + x * (1.0f/6.0f + x/24.0f)));
    return b2_exp(x) - 1.0f;
}
inline float b2_exprel(float x) {
    // Avoid cancellation in exp(x)-1 near zero. The first omitted term
    // is x^6/7!, below 8e-10 throughout this interval.
    if (abs(x) < 0.125f) return 1.0f + x * (0.5f + x * (1.0f/6.0f +
        x * (1.0f/24.0f + x * (1.0f/120.0f + x/720.0f))));
    // exp(x) overflows before exprel(x) does. Split only that range;
    // divide before multiplying so every intermediate of a finite result fits.
    // The subtracted 1/x is far below an f32 ulp in this range.
    if (x >= 88.722839f) {
        float half_exp = b2_exp(0.5f*x);
        return (half_exp/x)*half_exp;
    }
    return b2_expm1(x)/x;
}
inline float b2_log1p(float x) {
    if (abs(x) < 0.001f) return x * (1.0f + x * (-0.5f + x * (1.0f/3.0f - x/4.0f)));
    return log(1.0f + x);
}

inline ulong b2_mix64(ulong value) {
    value = (value ^ (value >> 30)) * 0xbf58476d1ce4e5b9ul;
    value = (value ^ (value >> 27)) * 0x94d049bb133111ebul;
    return value ^ (value >> 31);
}
inline float b2_uniform(ulong seed, ulong stream, ulong tick, ulong index, ulong draw) {
    ulong value = seed ^ stream*0x9e3779b97f4a7c15ul ^ tick*0xd1b54a32d192ed03ul
                 ^ index*0x94d049bb133111ebul ^ draw*0x369dea0f31a53f85ul;
    // Exactly representable samples in [0,1), never rounded up to one.
    return float(b2_mix64(value) >> 40) * 0x1p-24f;
}
inline float b2_normal(ulong seed, ulong stream, ulong tick, ulong index, thread bool *fault) {
    for (ulong draw=0; draw<8192; draw+=2) {
        float a=2.0f*b2_uniform(seed,stream,tick,index/2,draw)-1.0f;
        float b=2.0f*b2_uniform(seed,stream,tick,index/2,draw+1)-1.0f;
        float radius=a*a+b*b;
        if (radius<1.0f && radius!=0.0f)
            return sqrt(-2.0f*log(radius)/radius) * ((index & 1ul) ? b : a);
    }
    *fault=true; return 0.0f;
}

inline float b2_binomial_stirling(long count) {
    switch (count) {
case 1: return 0.08106146679532733f;
case 2: return 0.041340695955409013f;
case 3: return 0.027677925684998161f;
case 4: return 0.020790672103764063f;
case 5: return 0.016644691189822591f;
case 6: return 0.013876128823070655f;
case 7: return 0.011896709945891981f;
case 8: return 0.010411265261975f;
case 9: return 0.0092554621827090067f;
case 10: return 0.0083305634333590284f;
case 11: return 0.0075736754879520696f;
case 12: return 0.006942840107208692f;
case 13: return 0.0064089941880047796f;
case 14: return 0.0059513701127662522f;
case 15: return 0.005554733551961899f;
    }
    float inverse=1.0f/float(count), square=inverse*inverse;
    return inverse*(1.0f/12.0f+square*(-1.0f/360.0f+
                    square*(1.0f/1260.0f-square/1680.0f)));
}
inline float b2_binomial_deviance(long count, float mean, float delta) {
    float u=delta/mean;
    if (abs(u)<0.125f) return (delta*u)*(1.0f/2.0f + u*(-1.0f/6.0f + u*(1.0f/12.0f + u*(-1.0f/20.0f + u*(1.0f/30.0f + u*(-1.0f/42.0f + u*(1.0f/56.0f + u*(-1.0f/72.0f + u*(1.0f/90.0f + u*(-1.0f/110.0f + u*1.0f/132.0f))))))))));
    return float(count)*log(float(count)/mean)-delta;
}
inline float b2_binomial_mean_tail(ulong n, float p, float mean) {
    // Explicit fma recovers the product residual even with contraction disabled.
    // The integer residual also preserves n when it exceeds f32's exact range.
    float nf=float(n);
    return fma(nf,p,-mean)+float(long(n)-long(nf))*p;
}
inline float b2_binomial_log_mass(ulong n, long k, float p,
                                   long center, float fraction, float mean) {
    if (k==0) return float(n)*b2_log1p(-p);
    if (k==long(n)) return float(n)*log(p);
    long other=long(n)-k;
    float delta=float(k-center)-fraction;
    float complement=float(long(n)-center)-fraction;
    float deviance=b2_binomial_deviance(k,mean,delta)+
                   b2_binomial_deviance(other,complement,-delta);
    float normalizer=1.8378770664093455f+log(float(k))+log(float(other))-log(float(n));
    return b2_binomial_stirling(long(n))-b2_binomial_stirling(k)-b2_binomial_stirling(other)
           -deviance-0.5f*normalizer;
}
inline ulong b2_binomial_btrs(ulong seed, ulong stream, ulong tick, ulong index,
                             ulong n, float p, thread bool *fault) {
    float mean=float(n)*p;
    long center=long(mean);
    float fraction=(mean-float(center))+b2_binomial_mean_tail(n,p,mean);
    float sigma=sqrt(mean*(1.0f-p));
    float b=1.15f+2.53f*sigma, a=-0.0873f+0.0248f*b+0.01f*p;
    float squeeze=0.92f-4.2f/b, alpha=(2.83f+5.1f/b)*sigma;
    long mode=center+long(floor(fraction+p));
    float peak=b2_binomial_log_mass(n,mode,p,center,fraction,mean);
    for (ulong draw=0;draw<8192;draw+=2) {
        float horizontal=b2_uniform(seed,stream,tick,index,draw)-0.5f;
        float vertical=b2_uniform(seed,stream,tick,index,draw+1);
        float gap=0.5f-abs(horizontal);
        if (gap==0.0f) continue;
        long offset=long(floor((2.0f*a/gap+b)*horizontal+fraction+0.5f));
        long candidate=center+offset;
        if (candidate<0 || candidate>long(n)) continue;
        if (gap>=0.07f && vertical<=squeeze) return ulong(candidate);
        float envelope=log(vertical*alpha/(a/(gap*gap)+b));
        if (envelope<=b2_binomial_log_mass(n,candidate,p,center,fraction,mean)-peak)
            return ulong(candidate);
    }
    *fault=true; return 0ul;
}

inline float b2_binomial(ulong seed, ulong stream, ulong tick, ulong index,
                         ulong n, float p, bool approximate, thread bool *fault) {
    if (!(isfinite(p) && p>=0.0f && p<=1.0f)) { *fault=true; return 0.0f; }
    if (p==0.0f) return 0.0f;
    if (p==1.0f) return float(n);
    float mean=float(n)*p, complement=float(n)*(1.0f-p);
    if (approximate && mean>5.0f && complement>5.0f)
        return b2_normal(seed,stream,tick,index,fault)*sqrt(mean*(1.0f-p))+mean;
    bool reverse=p>0.5f;
    float probability=reverse ? 1.0f-p : p;
    float q=1.0f-probability;
    // log1p avoids losing low probabilities when q rounds to one.
    float initial=b2_exp(float(n)*b2_log1p(-probability));
    if (!(initial>0.0f && isfinite(initial))) {
        ulong sample=b2_binomial_btrs(seed,stream,tick,index,n,probability,fault);
        return float(reverse ? n-sample : sample);
    }
    float bound=float(n)*probability+10.0f*sqrt(float(n)*probability*q+1.0f);
    bound=bound<float(n) ? bound : float(n);
    for (ulong draw=0; draw<4096; ++draw) {
        ulong x=0;
        float mass=initial, u=b2_uniform(seed,stream,tick,index,draw);
        while (true) {
            if (u<=mass) return float(reverse ? n-x : x);
            ++x;
            if (float(x)>bound) break;
            u-=mass;
            mass=(float(n-x+1)*probability*mass)/(float(x)*q);
            if (!(mass>=0.0f && isfinite(mass))) { *fault=true; return 0.0f; }
        }
    }
    *fault=true; return 0.0f;
}

inline float b2_poisson_log_mass(long k, float rate, long center, float fraction) {
    if (k==0) return -rate;
    switch (k) {
case 1: return -rate+float(k)*log(rate);
case 2: return -rate+float(k)*log(rate)-0.69314718055994495f;
case 3: return -rate+float(k)*log(rate)-1.791759469228055f;
case 4: return -rate+float(k)*log(rate)-3.1780538303479444f;
case 5: return -rate+float(k)*log(rate)-4.7874917427820467f;
case 6: return -rate+float(k)*log(rate)-6.5792512120101012f;
case 7: return -rate+float(k)*log(rate)-8.5251613610654147f;
case 8: return -rate+float(k)*log(rate)-10.604602902745251f;
case 9: return -rate+float(k)*log(rate)-12.801827480081467f;
case 10: return -rate+float(k)*log(rate)-15.104412573075514f;
case 11: return -rate+float(k)*log(rate)-17.502307845873887f;
case 12: return -rate+float(k)*log(rate)-19.987214495661885f;
case 13: return -rate+float(k)*log(rate)-22.552163853123421f;
case 14: return -rate+float(k)*log(rate)-25.191221182738683f;
case 15: return -rate+float(k)*log(rate)-27.89927138384089f;
    }
    float x=float(k), delta=float(k-center)-fraction, u=delta/rate;
    float deviance;
    if (abs(u)<0.125f) deviance=(delta*u)*(1.0f/2.0f + u*(-1.0f/6.0f + u*(1.0f/12.0f + u*(-1.0f/20.0f + u*(1.0f/30.0f + u*(-1.0f/42.0f + u*(1.0f/56.0f + u*(-1.0f/72.0f + u*(1.0f/90.0f + u*(-1.0f/110.0f + u*1.0f/132.0f))))))))));
    else deviance=x*log(x/rate)-delta;
    float inverse=1.0f/x, square=inverse*inverse;
    float correction=inverse*(1.0f/12.0f+square*(-1.0f/360.0f+
                         square*(1.0f/1260.0f-square/1680.0f)));
    return -deviance-0.9189385332046727f-0.5f*log(x)-correction;
}

inline float b2_poisson(ulong seed, ulong stream, ulong tick, ulong index,
                        float rate, thread bool *fault) {
    if (!(isfinite(rate) && rate>=0.0f && rate<=1.0e12f)) {
        *fault=true; return 0.0f;
    }
    if (rate==0.0f) return 0.0f;
    if (rate<10.0f) {
        float limit=b2_exp(-rate), product=1.0f;
        for (ulong draw=0;draw<8192; ++draw) {
            product*=b2_uniform(seed,stream,tick,index,draw);
            if (product<=limit) return float(draw);
        }
        *fault=true; return 0.0f;
    }
    float root=sqrt(rate), b=0.931f+2.53f*root;
    float a=-0.059f+0.02483f*b;
    float inverse_alpha=1.1239f+1.1328f/(b-3.4f);
    float squeeze=0.9277f-3.6224f/(b-2.0f);
    long center=long(rate);
    float fraction=rate-float(center);
    for (ulong draw=0;draw<8192;draw+=2) {
        float u=b2_uniform(seed,stream,tick,index,draw)-0.5f;
        float v=b2_uniform(seed,stream,tick,index,draw+1);
        float us=0.5f-abs(u);
        if (us==0.0f) continue;
        float offset=floor((2.0f*a/us+b)*u+fraction+0.43f);
        // The largest offset under the U24 grid and rate bound is < 2^41.
        // Keep the candidate's low integer bits until acceptance; adding it
        // to a large f32 mean first would quantize the rejection decision.
        long k=center+long(offset);
        if (k<0) continue;
        if (us>=0.07f && v<=squeeze) return float(k);
        if (us<0.013f && v>us) continue;
        float left=log(v*inverse_alpha/(a/(us*us)+b));
        if (left<=b2_poisson_log_mass(k,rate,center,fraction)) return float(k);
    }
    *fault=true; return 0.0f;
}

inline float b2_timed_array(device const float *values, ulong offset,
                            uint rows, uint width, float epsilon, float upsampling,
                            float time, float column, thread bool *fault) {
    if (!(isfinite(column) && column>=0.0f && column<float(width))) {
        *fault=true; return 0.0f;
    }
    float raw=(time/epsilon+0.5f)/upsampling;
    // Saturate before converting to an integer, including +/-infinity and NaN.
    // B2IR's saturating conversion maps NaN/negative time to the first row.
    uint row=!(raw>0.0f) ? 0u : (raw>=float(rows-1) ? rows-1 : uint(raw));
    return values[offset+ulong(row)*width+uint(column)];
}
inline int b2_cast_i32(float x) {
    if (isnan(x)) return int(0);
    if (x <= -0x1p31f) return as_type<int>(0x80000000u);
    if (x >= 0x1p31f) return as_type<int>(0x7fffffffu);
    return int(x);
}
inline int b2_div_i32(int a, int b, bool modulo, thread bool *fault) {
    if (b==0) { *fault=true; return int(0); }
    if (a==as_type<int>(0x80000000u) && b==int(-1)) return modulo ? int(0) : a;
    int q=a/b, r=a%b;
    if (r != 0 && (r < 0) != (b < 0)) { q=as_type<int>(uint(uint(q)-1)); r=as_type<int>(uint(uint(r)+uint(b))); }
    return modulo ? r : q;
}
inline long b2_cast_i64(float x) {
    if (isnan(x)) return long(0);
    if (x <= -0x1p63f) return as_type<long>(0x8000000000000000ul);
    if (x >= 0x1p63f) return as_type<long>(0x7ffffffffffffffful);
    return long(x);
}
inline long b2_div_i64(long a, long b, bool modulo, thread bool *fault) {
    if (b==0) { *fault=true; return long(0); }
    if (a==as_type<long>(0x8000000000000000ul) && b==long(-1)) return modulo ? long(0) : a;
    long q=a/b, r=a%b;
    if (r != 0 && (r < 0) != (b < 0)) { q=as_type<long>(ulong(ulong(q)-1)); r=as_type<long>(ulong(ulong(r)+ulong(b))); }
    return modulo ? r : q;
}
inline uint b2_cast_u32(float x) {
    if (isnan(x)) return uint(0);
    if (x <= 0.0f) return 0u;
    if (x >= 0x1p32f) return 0xffffffffu;
    return uint(x);
}
inline uint b2_div_u32(uint a, uint b, bool modulo, thread bool *fault) {
    if (b==0) { *fault=true; return uint(0); }

    uint q=a/b, r=a%b;

    return modulo ? r : q;
}
inline ulong b2_cast_u64(float x) {
    if (isnan(x)) return ulong(0);
    if (x <= 0.0f) return 0u;
    if (x >= 0x1p64f) return 0xfffffffffffffffful;
    return ulong(x);
}
inline ulong b2_div_u64(ulong a, ulong b, bool modulo, thread bool *fault) {
    if (b==0) { *fault=true; return ulong(0); }

    ulong q=a/b, r=a%b;

    return modulo ? r : q;
}
inline float b2_float_div(float a, float b, bool modulo, thread bool *fault) {
    if (!isfinite(a) || !isfinite(b) || b==0.0f) { *fault=true; return 0.0f; }
    float q=floor(a/b);
    float result=modulo ? a-q*b : q;
    if (!isfinite(result)) { *fault=true; return 0.0f; }
    return result;
}

inline void stage_0(
    device float *state , device const float *parameters ,
    device float *trace , device const int *record_slot ,
    device long *spike_ticks , device uint *spike_counts ,
    device uchar *last_fired , device long *last_tick ,
    device long *until_tick , device uchar *not_refractory ,
    device float *initial_last_time , device uchar *event_history , constant long &tick , uint i ) {
    if (i >= 4096u) return;
    long last = last_tick[i];
    long until = until_tick[i];
    bool math_error = until < 0;
    bool available = not_refractory[i] != 0;
    float last_time = initial_last_time[i];
    bool fired = last_fired[i] != 0;
    uint emitted = spike_counts[i];
    int record = record_slot[i];
    float s0 = state[0+(i)];
    {
        float time = float(tick) * as_type<float>(0x3a800000u);
        {
            float x0 = b2_finite(float(((float(s0)) + (as_type<float>(0x3c800000u)))), &math_error);
            float x1 = float(x0);
            s0 = x1;
        }
        if (record >= 0 && tick >= 0) {
            trace[0+((tick-0)*2+record)] = s0;
        }
        {
            float x0 = b2_finite(float((((-(as_type<float>(0x3a800000u)))) / (parameters[0+(0)]))), &math_error);
            float x1 = float(x0);
            float x2 = b2_finite(float(((float(x1)) * (float(s0)))), &math_error);
            float x3 = b2_finite(float(((x2) + (float(s0)))), &math_error);
            float x4 = float(x3);
            s0 = x4;
        }
        {
            bool x0 = ((float(s0)) > (float(as_type<long>(0x1ul))));
            fired = x0;
            if (tick >= 0) event_history[0+(tick-0)*4096+i] = uchar(fired);
        }
        if (fired && tick >= 0) spike_ticks[ulong(i)*1024+emitted++] = tick;
    }
    state[0+(i)] = s0;
    initial_last_time[i] = last_time;
    spike_counts[i] = emitted; last_fired[i] = uchar(fired);
    last_tick[i] = last; until_tick[i] = math_error ? -1 : until; not_refractory[i] = uchar(available);
}
inline void stage_1_target_pathway_history(device const uchar *fired , device uchar *history ,
    constant long &tick , uint lane ) {
    if (lane >= 4096u) return;
    history[ulong(tick%16)*4096+lane]=fired[lane+0];
}

inline void stage_0_with_pathway_history(device float *b0 ,
    device const float *b1 ,
    device float *b2 ,
    device const int *b3 ,
    device long *b4 ,
    device uint *b5 ,
    device uchar *b6 ,
    device long *b7 ,
    device long *b8 ,
    device uchar *b9 ,
    device float *b10 ,
    device uchar *b11 ,
    device uchar *b12 , constant long &tick ,
    uint i ) {
    stage_0(b0, b1, b2, b3, b4, b5, b6, b7, b8, b9, b10, b11,tick,i);
    stage_1_target_pathway_history(b6, b12,tick,i);
}

inline void stage_2_edge_pathway_history(device const uchar *fired , device uchar *history ,
    constant long &tick , uint lane ) {
    if (lane >= 4096u) return;
    history[ulong(tick%17)*4096+lane]=fired[lane+0];
}

kernel void stage_0_with_pathway_history_with_pathway_history(device float *b0 [[buffer(0)]],
    device const float *b1 [[buffer(1)]],
    device float *b2 [[buffer(2)]],
    device const int *b3 [[buffer(3)]],
    device long *b4 [[buffer(4)]],
    device uint *b5 [[buffer(5)]],
    device uchar *b6 [[buffer(6)]],
    device long *b7 [[buffer(7)]],
    device long *b8 [[buffer(8)]],
    device uchar *b9 [[buffer(9)]],
    device float *b10 [[buffer(10)]],
    device uchar *b11 [[buffer(11)]],
    device uchar *b12 [[buffer(12)]],
    device uchar *b13 [[buffer(13)]], constant long &tick [[buffer(14)]],
    uint i [[thread_position_in_grid]]) {
    stage_0_with_pathway_history(b0, b1, b2, b3, b4, b5, b6, b7, b8, b9, b10, b11, b12,tick,i);
    stage_2_edge_pathway_history(b6, b13,tick,i);
}

#include <metal_stdlib>
using namespace metal;
#pragma clang fp contract(off)
inline long b2_timestep(float value, float dt, thread bool *fault) {
    float steps = (value + 1e-3f*dt)/dt;
    if (!(value >= 0.0f && isfinite(dt) && dt > 0.0f && isfinite(steps) && steps <= 0x1p53f)) {
        *fault = true;
        return 0;
    }
    return long(steps);
}
inline long b2_tick_offset(long tick, long offset, thread bool *fault) {
    // Frozen B2IR evaluates logical ticks as f64. The boundary ties
    // +(2^53+1) and -(2^53+1) round to +/-2^53 and are accepted there.
    // Check before addition so even invalid inputs cannot overflow int64.
    const long limit = 9007199254740992l;
    const long allowed = limit + 1l;
    if (tick > allowed-offset || tick < -allowed-offset) {
        *fault = true;
        return 0;
    }
    long result = tick + offset;
    return result > limit ? limit : (result < -limit ? -limit : result);
}
inline float b2_finite(float value, thread bool *error) {
