inline void stage_0(
    device float *state , device const float *parameters ,
    device float *trace , device const int *record_slot ,
    device long *spike_ticks , device uint *spike_counts ,
    device uchar *last_fired , device long *last_tick ,
    device long *until_tick , device uchar *not_refractory ,
    device float *initial_last_time , device uchar *event_history , constant long &tick , uint i ) {
    if (i >= 4096u) return;
    long last = last_tick[i];
    long until = until_tick[i];
    bool math_error = until < 0;
    bool available = not_refractory[i] != 0;
    float last_time = initial_last_time[i];
    bool fired = last_fired[i] != 0;
    uint emitted = spike_counts[i];
    int record = record_slot[i];
    float s0 = state[0+(i)];
    {
        float time = float(tick) * as_type<float>(0x3a800000u);
        {
            float x0 = b2_finite(float(((float(s0)) + (as_type<float>(0x3c800000u)))), &math_error);
            float x1 = float(x0);
            s0 = x1;
        }
        if (record >= 0 && tick >= 0) {
            trace[0+((tick-0)*2+record)] = s0;
        }
        {
            float x0 = b2_finite(float((((-(as_type<float>(0x3a800000u)))) / (parameters[0+(0)]))), &math_error);
            float x1 = float(x0);
            float x2 = b2_finite(float(((float(x1)) * (float(s0)))), &math_error);
            float x3 = b2_finite(float(((x2) + (float(s0)))), &math_error);
            float x4 = float(x3);
            s0 = x4;
        }
        {
            bool x0 = ((float(s0)) > (float(as_type<long>(0x1ul))));
            fired = x0;
            if (tick >= 0) event_history[0+(tick-0)*4096+i] = uchar(fired);
        }
        if (fired && tick >= 0) spike_ticks[ulong(i)*1024+emitted++] = tick;
    }
    state[0+(i)] = s0;
    initial_last_time[i] = last_time;
    spike_counts[i] = emitted; last_fired[i] = uchar(fired);
    last_tick[i] = last; until_tick[i] = math_error ? -1 : until; not_refractory[i] = uchar(available);
}
inline void stage_1_target_pathway_history(device const uchar *fired , device uchar *history ,
    constant long &tick , uint lane ) {
    if (lane >= 4096u) return;
    history[ulong(tick%16)*4096+lane]=fired[lane+0];
}

inline void stage_0_with_pathway_history(device float *b0 ,
    device const float *b1 ,
