case 8: return -rate+float(k)*log(rate)-10.604602902745251f;
case 9: return -rate+float(k)*log(rate)-12.801827480081467f;
case 10: return -rate+float(k)*log(rate)-15.104412573075514f;
case 11: return -rate+float(k)*log(rate)-17.502307845873887f;
case 12: return -rate+float(k)*log(rate)-19.987214495661885f;
case 13: return -rate+float(k)*log(rate)-22.552163853123421f;
case 14: return -rate+float(k)*log(rate)-25.191221182738683f;
