    // B2IR's saturating conversion maps NaN/negative time to the first row.
    uint row=!(raw>0.0f) ? 0u : (raw>=float(rows-1) ? rows-1 : uint(raw));
    return values[offset+ulong(row)*width+uint(column)];
}
