inline void stage_0(
    device float *state , device const float *parameters ,
    device float *trace , device const int *record_slot ,
    device long *spike_ticks , device uint *spike_counts ,
    device uchar *last_fired , device long *last_tick ,
    device long *until_tick , device uchar *not_refractory ,
    device float *initial_last_time , device uchar *event_history , constant long &tick , uint i ) {
    if (i >= 4096u) return;
    long last = last_tick[i];
    long until = until_tick[i];
    bool math_error = until < 0;
    bool available = not_refractory[i] != 0;
    float last_time = initial_last_time[i];
    bool fired = last_fired[i] != 0;
    uint emitted = spike_counts[i];
    int record = record_slot[i];
    float s0 = state[0+(i)];
    {
        float time = float(tick) * as_type<float>(0x3a800000u);
        {
            float x0 = b2_finite(float(((float(s0)) + (as_type<float>(0x3d800000u)))), &math_error);
            float x1 = float(x0);
            s0 = x1;
        }
        if (record >= 0 && tick >= 0) {
            trace[0+((tick-0)*2+record)] = s0;
        }
        {
            float x0 = b2_finite(float((((-(as_type<float>(0x3a800000u)))) / (parameters[0+(0)]))), &math_error);
            float x1 = float(x0);
            float x2 = b2_finite(float(((float(x1)) * (float(s0)))), &math_error);
            float x3 = b2_finite(float(((x2) + (float(s0)))), &math_error);
            float x4 = float(x3);
            s0 = x4;
        }
        {
            bool x0 = ((float(s0)) > (float(as_type<long>(0x1ul))));
            fired = x0;
            if (tick >= 0) event_history[0+(tick-0)*4096+i] = uchar(fired);
        }
        if (fired && tick >= 0) spike_ticks[ulong(i)*1024+emitted++] = tick;
    }
    state[0+(i)] = s0;
    initial_last_time[i] = last_time;
    spike_counts[i] = emitted; last_fired[i] = uchar(fired);
    last_tick[i] = last; until_tick[i] = math_error ? -1 : until; not_refractory[i] = uchar(available);
}
inline void stage_1_delay_sparse_enqueue(device const uchar *fired ,
    device uchar *history , device const uint *source_groups ,
    device const uint *group_delays , device const uint *group_offsets ,
    device const uint *group_ranks , device const uint *rank_targets ,
    device const uint *target_offsets , device uint *active ,
    device const uint *counts , constant long &tick ,
    uint i ) {
    if (i >= 4096u) return;
    history[ulong(tick%8)*4096+i] = fired[i+0];
    for (uint group=source_groups[i]; group<source_groups[i+1]; ++group) {
        long emission=tick-long(group_delays[group]);
        if (emission < 0 || !history[ulong(emission%8)*4096+i]) continue;
        for (uint at=group_offsets[group]; at<group_offsets[group+1]; ++at) {
            uint rank=group_ranks[at];
            uint target=rank_targets[rank];
            uint base=target_offsets[target], relative=rank-base;
            atomic_fetch_or_explicit((device atomic_uint *)&active[counts[target]+relative/32],
                1u<<(relative%32),memory_order_relaxed);
        }
    }
}

inline void stage_0_with_source_enqueue(device float *b0 ,
    device const float *b1 ,
    device float *b2 ,
    device const int *b3 ,
    device long *b4 ,
    device uint *b5 ,
    device uchar *b6 ,
    device long *b7 ,
    device long *b8 ,
    device uchar *b9 ,
