    stage_1_delay_sparse_enqueue(b6, b12, b13, b14, b15, b16, b17, b18, b19, b20,tick,i);
}

inline void stage_2_edge_pathway_history(device const uchar *fired , device uchar *history ,
    constant long &tick , uint lane ) {
    if (lane >= 4096u) return;
