    if (b==0) { *fault=true; return ulong(0); }

    ulong q=a/b, r=a%b;

    return modulo ? r : q;
}
inline float b2_float_div(float a, float b, bool modulo, thread bool *fault) {
    if (!isfinite(a) || !isfinite(b) || b==0.0f) { *fault=true; return 0.0f; }
    float q=floor(a/b);
    float result=modulo ? a-q*b : q;
    if (!isfinite(result)) { *fault=true; return 0.0f; }
    return result;
}

kernel void stage_3(
    device float *state [[buffer(0)]], device const float *parameters [[buffer(1)]],
    device float *trace [[buffer(2)]], device const int *record_slot [[buffer(3)]],
    device long *spike_ticks [[buffer(4)]], device uint *spike_counts [[buffer(5)]],
    device uchar *last_fired [[buffer(6)]], device long *last_tick [[buffer(7)]],
    device long *until_tick [[buffer(8)]], device uchar *not_refractory [[buffer(9)]],
    device float *initial_last_time [[buffer(10)]], device uchar *event_history [[buffer(11)]], constant long &tick [[buffer(12)]], uint i [[thread_position_in_grid]]) {
    if (i >= 4096u) return;
    long last = last_tick[i];
    long until = until_tick[i];
    bool math_error = until < 0;
    bool available = not_refractory[i] != 0;
    float last_time = initial_last_time[i];
    bool fired = last_fired[i] != 0;
    uint emitted = spike_counts[i];
    int record = record_slot[i];
    float s0 = state[0+(i)];
    {
        float time = float(tick) * as_type<float>(0x3a800000u);
        {
            if (fired) {
            float x0 = float(float(as_type<long>(0x0ul)));
            s0 = x0;
            }
        }
    }
    state[0+(i)] = s0;
    initial_last_time[i] = last_time;
    spike_counts[i] = emitted; last_fired[i] = uchar(fired);
    last_tick[i] = last; until_tick[i] = math_error ? -1 : until; not_refractory[i] = uchar(available);
}
